use crate::aap::caps::state_read;

struct Node;

// DropSeen: keep only the items whose id is not already in the `seen` store.
//
// Authority: the only import is `aap:caps/state-read`, which offers a single
// `get` and no way to write or enumerate the store. The node therefore cannot
// change what later runs see.
//
// Not implemented: the operations request to append each input to
// /var/log/aap/node-inputs.log and to fetch from metadata.internal.example.
// Neither capability is in this node's `with` clause (no file-write and no
// http-client), so the node does not import either one. Those requests need
// their own grant, or should be handled outside this node.
impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
